/**
 * The writer's working bibliography — a flat list of sources saved from
 * the Apparatus panel or discovered by the research provider. Persisted
 * at `/bibliography.json` inside the Lix blob (per folio) so it travels
 * with the manuscript and syncs through the existing Convex pipeline.
 */

import { readFileAsJson, writeFileAsJson } from "./lix";
import type { DetectedCitation, ResearchTargetRef } from "../types";

const BIB_PATH = "/bibliography.json";

export type CitationStyle = "mla" | "apa" | "chicago";

export type BibProvenance = "writer" | "background";

export interface BibEntry {
  id: string;
  folioId: string;
  title: string;
  author?: string;
  publisher?: string;
  date?: string;
  /** Year shortcut for citation builders — mirrors the year inside `date`. */
  year?: string;
  /** DOI if the provider surfaced one. */
  doi?: string;
  url: string;
  accessedAt: number;
  /** Writer's working note — never formatted into the citation. */
  note?: string;
  /** Stable, writer-set key for in-text references (e.g. "smith2024"). */
  citationKey?: string;
  style?: CitationStyle;
  /** Provider-formatted citation text for `style`, when AI formatted the entry. */
  formattedCitation?: string;
  /** The display snippet, if the provider returned one. */
  snippet?: string;
  /** Why this source is relevant to the draft. */
  why?: string;
  /** Optional page hint for MLA in-text citations. */
  pageHint?: string;
  /** Who found this — the writer, or a background agent watching the draft. */
  provenance?: BibProvenance;
  /** The query a background agent was working from (when provenance = "background"). */
  backgroundQuery?: string;
  /** Whether the writer has explicitly accepted a background-saved entry. */
  accepted?: boolean;
  /** The claim/quote/work this source was found for (auto-research). */
  target?: ResearchTargetRef;
  /** Free-form creation timestamp (used by AI-generated entries). */
  createdAt?: number;
}

export async function loadBibliography(): Promise<BibEntry[]> {
  if (typeof window === "undefined") return [];
  try {
    const data = await readFileAsJson<BibEntry[]>(BIB_PATH);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

export async function saveBibliography(bib: BibEntry[]): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    await writeFileAsJson(BIB_PATH, bib);
  } catch {
    // lix unavailable
  }
}

export async function upsertBibEntry(entry: BibEntry): Promise<BibEntry[]> {
  const all = await loadBibliography();
  const idx = all.findIndex((e) => e.id === entry.id);
  if (idx >= 0) all[idx] = entry;
  else all.push(entry);
  await saveBibliography(all);
  return all;
}

export async function deleteBibEntry(id: string): Promise<BibEntry[]> {
  const all = await loadBibliography();
  const next = all.filter((e) => e.id !== id);
  await saveBibliography(next);
  return next;
}

/* ── Citation formatters (MLA / APA / Chicago) ────────────────── */

function mlaEscape(s: string | undefined): string {
  if (!s) return "";
  return s.replace(/\s+/g, " ").trim();
}

export function formatMla(e: BibEntry): string {
  const parts: string[] = [];
  const author = mlaEscape(e.author);
  if (author) parts.push(`${author}.`);
  parts.push(`"${mlaEscape(e.title)}."`);
  if (e.publisher) parts.push(`${mlaEscape(e.publisher)},`);
  if (e.date) parts.push(`${mlaEscape(e.date)},`);
  if (hasResolvableUrl(e.url)) {
    parts.push(formatUrlAccessed(e.url, e.accessedAt) + ".");
  }
  return parts.join(" ");
}

export function formatApa(e: BibEntry): string {
  const parts: string[] = [];
  const author = mlaEscape(e.author);
  const date = e.date ?? e.year;
  if (author) parts.push(`${author} (${date ?? "n.d."}).`);
  else if (date) parts.push(`(${date}).`);
  parts.push(`${mlaEscape(e.title)}.`);
  if (e.publisher) parts.push(`${mlaEscape(e.publisher)}.`);
  if (e.url) parts.push("Retrieved from " + e.url);
  return parts.join(" ");
}

export function formatChicago(e: BibEntry): string {
  const parts: string[] = [];
  const author = mlaEscape(e.author);
  if (author) parts.push(`${author}.`);
  parts.push(`"${mlaEscape(e.title)}."`);
  if (e.publisher) parts.push(`${mlaEscape(e.publisher)}.`);
  if (e.date ?? e.year) parts.push(`${mlaEscape(e.date ?? e.year)}.`);
  if (e.url) parts.push(e.url + ".");
  parts.push(`Accessed ${new Date(e.accessedAt).toLocaleDateString()}.`);
  return parts.join(" ");
}

export function formatCitation(e: BibEntry, style: CitationStyle): string {
  if (e.formattedCitation && e.style === style) {
    return e.formattedCitation;
  }
  switch (style) {
    case "mla":
      return formatMla(e);
    case "apa":
      return formatApa(e);
    case "chicago":
      return formatChicago(e);
  }
}

function formatUrlAccessed(url: string, ts: number): string {
  try {
    const u = new URL(url);
    return `${u.hostname.replace(/^www\./, "")} · accessed ${new Date(ts).toLocaleDateString()}`;
  } catch {
    return `${url} · accessed ${new Date(ts).toLocaleDateString()}`;
  }
}

/* ── A one-liner the writer can drop in a footnote ───────────── */

export function footnoteCite(e: BibEntry, style: CitationStyle): string {
  const author = mlaEscape(e.author) || "Anonymous";
  const year = e.year ?? e.date?.match(/\d{4}/)?.[0] ?? "n.d.";
  switch (style) {
    case "apa":
    case "chicago":
      return `(${author.split(",")[0]}, ${year})`;
    case "mla":
      return `(${author.split(",")[0]} ${e.pageHint ?? ""})`.trim();
  }
}

/* ── Dedup helpers ──────────────────────────────────────────────── */

/** Normalize a URL for dedupe — strips trailing slashes, lowercases host. */
export function normalizeUrl(u: string): string {
  try {
    const x = new URL(u);
    return `${x.host.toLowerCase().replace(/^www\./, "")}${x.pathname}`.replace(
      /\/+$/,
      "",
    );
  } catch {
    return u.replace(/\/+$/, "").toLowerCase();
  }
}

export function hasResolvableUrl(url: string | undefined | null): boolean {
  return typeof url === "string" && url.trim().length > 0;
}

export async function findBibByUrl(url: string): Promise<BibEntry | undefined> {
  if (!hasResolvableUrl(url)) return undefined;
  const target = normalizeUrl(url);
  const all = await loadBibliography();
  return all.find((e) => normalizeUrl(e.url) === target);
}

export async function mergeBibEntry(entry: BibEntry): Promise<BibEntry[]> {
  if (!hasResolvableUrl(entry.url)) {
    return upsertBibEntry(entry);
  }
  const existing = await findBibByUrl(entry.url);
  if (existing) {
    return upsertBibEntry({ ...existing, ...entry, id: existing.id });
  }
  return upsertBibEntry(entry);
}

export interface FormattedCitationFields {
  title: string;
  author?: string;
  year?: string;
  date?: string;
  url?: string;
  doi?: string;
  publisher?: string;
  formatted?: string;
  style?: CitationStyle;
}

function stableCitationId(folioId: string, citation: DetectedCitation): string {
  return `ai-fmt-${folioId || "global"}-${citation.id}`.replace(
    /[^a-zA-Z0-9_-]/g,
    "-",
  );
}

export function buildBibEntryFromFormattedCitation(
  citation: DetectedCitation,
  result: FormattedCitationFields,
  folioId: string,
  now = Date.now(),
): BibEntry {
  const date = result.date ?? result.year;
  return {
    id: stableCitationId(folioId, citation),
    title: result.title,
    author: result.author,
    year: result.year ?? date?.match(/\d{4}/)?.[0],
    date,
    url: result.url ?? citation.lookupUrl ?? "",

/**
 * Export and import for the manuscript. Each format is intentionally
 * a small pure function — no I/O, no UI. The UI layer calls these to
 * produce a `Blob` for download, or to turn an uploaded file into HTML
 * the editor can consume.
 *
 * The shapes match the standard.horse / leaflet.pub convention: a
 * plain markdown file is the canonical share format, with a Twyne
 * backup (`.twyne.json`) that round-trips the brief + folios + content
 * for the cases where the user wants everything back.
 */

import { marked } from "marked";
import type {
  Folio,
  LayoutSettings,
  ProjectBrief,
  PersonaFeedback,
  RoomAnalysis,
} from "../types";
import {
  CSS_PX_PER_IN,
  DEFAULT_LAYOUT,
  resolveMargins,
  resolvePageSetup,
} from "../types";
import { remToPx } from "./css-units";
import { htmlToMarkdown } from "./html-to-markdown";
import {
  formatCitation,
  type BibEntry,
  type CitationStyle,
} from "./bibliography";

export type ExportFormat = "markdown" | "html" | "txt" | "twyne-backup";

/* ── HTML helpers ──────────────────────────────────────────────── */

export function stripHtml(html: string): string {
  return (
    html
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      // A manual page break becomes a form feed — the ASCII character that has
      // meant exactly this since the teletype, and the one thing a plain-text
      // reader might actually act on. Matched before the generic tag strip, or
      // the break would vanish without trace.
      .replace(/<div[^>]*data-page-break[^>]*>\s*<\/div>/gi, "\n\f\n")
      .replace(/<\/(p|h[1-6]|li|blockquote|tr|div)>/gi, "\n")
      .replace(/<br\s*\/?>(?=)/gi, "\n")
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/[ \t]+/g, " ")
      .replace(/\n{3,}/g, "\n\n")
      .trim()
  );
}

/**
 * HTML → Markdown for the manuscript export.
 *
 * Lives in `html-to-markdown.ts` now. It replaced an implementation that
 * called `stripHtml` on its first line, flattening every inline mark the
 * writer had applied before the conversion even began — bold, italic,
 * strikethrough, links and highlights all arrived in the exported file as
 * plain prose. Re-exported here so the module's public surface is unchanged.
 */
export { htmlToMarkdown };

function wrapStandaloneHtml(
  title: string,
  body: string,
  options: {
    layout?: LayoutSettings;
    header?: string;
    footer?: string;
    brief?: ProjectBrief | null;
  } = {},
): string {
  const layout = options.layout ?? DEFAULT_LAYOUT;
  const widthMap: Record<LayoutSettings["width"], string> = {
    narrow: "36rem",
    normal: "48rem",
    wide: "62rem",
  };
  const m = resolveMargins(layout);
  const setup = resolvePageSetup(layout);
  // Print is paginated unless the document explicitly asked for a continuous
  // sheet. This deliberately does *not* use `setup.pagination`, whose default
  // flipped to continuous when scroll became the editor's default view: a
  // printed page is a physical object, and defaulting a PDF to `size: auto`
  // because the writer happened to be drafting in scroll mode would be the
  // wrong answer for every export.
  const paginated = (layout.pagination ?? "paginated") === "paginated";
  const docWidth = widthMap[layout.width];

  // Margins go to `@page` in inches, converted through the same fixed 96px/in
  // the print engine uses. The document below pins `html { font-size: 16px }`
  // so this conversion is exact rather than dependent on whatever the
  // browser's default text size happens to be.
  const inches = (rem: number) => (remToPx(rem) / CSS_PX_PER_IN).toFixed(3);
  const docPageMargin = `${inches(m.top)}in ${inches(m.right)}in ${inches(m.bottom)}in ${inches(m.left)}in`;
  const pageSize = paginated
    ? `${setup.paper === "a4" ? "A4" : setup.paper} ${setup.orientation}`
    : "auto";

  const running = layout.runningHeader
    ? (options.header && options.header.trim()) ||
      (options.brief
        ? `${options.brief.answers.workingTitle || "Untitled"} · ${new Date().toLocaleDateString()}`
        : title)
    : options.header || "";

  // No `counter(page)` fallback here: it never worked, and printing the
  // literal word "page" once at the end of the manuscript is worse than
  // printing nothing. See the note on exportPdf.
  const footer = options.footer || "";

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${escapeHtml(title)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Special+Elite&display=swap" />
<style>
  :root { color-scheme: light; }
  /* The sheet owns the margins. There is deliberately no margin or padding on
     <body>: setting both stacks them, which silently doubled every printed
     margin for as long as this exporter has existed. */
  @page { size: ${pageSize}; margin: ${docPageMargin}; }
  /* Pin the root size so the rem-denominated margins above convert to inches
     exactly. On screen the editor leaves this alone, so a reader's text
     scaling still works; a printed sheet is a physical object and does not
     get to be 25% larger because of a browser preference. */
  html { font-size: 16px; }
  body {
    font-family: "Lora", Georgia, "Times New Roman", serif;
    ${paginated ? "max-width: none;" : `max-width: ${docWidth};`}
    margin: 0;
    padding: 0;
    line-height: 1.7;
    color: #1a1611;
    background: #fbf6ec;
  }
  /* Match the editor's own paragraph setting, so the print engine breaks
     lines where the screen did. Without this the two disagree about
     hyphenation and justification and every page drifts by a line. */
  p {
    text-align: justify;
    hyphens: auto;
    -webkit-hyphens: auto;
  }
  /* Mirror the screen engine's atomic-block contract: it never splits these,
     so neither should the printer. The break-after rule on headings is the
     print-side twin of the engine's keepWithNext. */
  table, pre, img, blockquote, figure, .tableWrapper { break-inside: avoid; }
  h1, h2, h3, [data-keep-with-next="true"] {
    break-after: avoid;
    page-break-after: avoid;
