      folioId: created.id,
      include: ["content", "brief", "feedback", "rubric", "suggestions", "citations"],
    });
    expect(bundle).toMatchObject({
      folio: { id: created.id, name: "A field guide", type: "draft" },
      html: "<p>First draft.</p>",
