export const TWYNE_ARCHIVE_FORMAT = "twyne-archive" as const;
export const TWYNE_ARCHIVE_VERSION = 2 as const;

export interface TwyneArchiveV2 {
  format: typeof TWYNE_ARCHIVE_FORMAT;
  version: typeof TWYNE_ARCHIVE_VERSION;
  exportedAt: string;
  folios: FolioBundle[];
}

export interface ImportSource {
  name: string;
  content: string;
  type?: FolioType;
}

export interface ParsedImport {
  folios: FolioBundle[];
  sourceFormat: "archive" | "markdown" | "html" | "txt";
}

export type SingleExportFormat = "markdown" | "html" | "txt";
export type ExportFormat = "archive" | SingleExportFormat;

export interface ExportArtifact {
  format: ExportFormat;
  mimeType: string;
  suggestedFilename: string;
  content: string;
}

export interface ImportSummary {
  imported: Folio[];
  citationsSaved: number;
  warnings: string[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function requireFolio(value: unknown, index: number): Folio {
  if (!isRecord(value) || typeof value.name !== "string" || !value.name.trim()) {
    throw new Error(`Archive folio ${index + 1} must contain a non-empty folio.name`);
  }
  if (value.id !== undefined && typeof value.id !== "string") {
    throw new Error(`Archive folio ${index + 1} has an invalid folio.id`);
  }
  return value as Folio;
}

export function createArchive(folios: FolioBundle[], now = new Date()): TwyneArchiveV2 {
  return {
    format: TWYNE_ARCHIVE_FORMAT,
    version: TWYNE_ARCHIVE_VERSION,
    exportedAt: now.toISOString(),
    folios,
  };
}

export function parseArchive(input: string | unknown): TwyneArchiveV2 {
  let parsed: unknown = input;
  if (typeof input === "string") {
    try {
      parsed = JSON.parse(input);
    } catch (error) {
      throw new Error(
        `Twyne archive is not valid JSON: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
  if (!isRecord(parsed)) throw new Error("Twyne archive must be a JSON object");
  if (parsed.format !== TWYNE_ARCHIVE_FORMAT || parsed.version !== TWYNE_ARCHIVE_VERSION) {
    throw new Error(
      `Expected a ${TWYNE_ARCHIVE_FORMAT} version ${TWYNE_ARCHIVE_VERSION} bundle`,
    );
  }
  if (!Array.isArray(parsed.folios)) throw new Error("Twyne archive folios must be an array");
  const folios = parsed.folios.map((entry, index): FolioBundle => {
    if (!isRecord(entry)) throw new Error(`Archive folio ${index + 1} must be an object`);
    const folio = requireFolio(entry.folio, index);
    if (entry.html !== undefined && typeof entry.html !== "string") {
      throw new Error(`Archive folio ${index + 1} has invalid html`);
    }
    if (entry.citations !== undefined && !Array.isArray(entry.citations)) {
      throw new Error(`Archive folio ${index + 1} has invalid citations`);
    }
    return { ...entry, folio } as FolioBundle;
  });
  return {
    format: TWYNE_ARCHIVE_FORMAT,
    version: TWYNE_ARCHIVE_VERSION,
    exportedAt: typeof parsed.exportedAt === "string" ? parsed.exportedAt : new Date(0).toISOString(),
    folios,
  };
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function decodeHtml(value: string): string {
  return value
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&#x27;/gi, "'");
}

export function stripHtml(html: string): string {
  return decodeHtml(
    html
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<br\s*\/?\s*>/gi, "\n")
      .replace(/<\/(p|h[1-6]|li|blockquote|tr|div)>/gi, "\n")
      .replace(/<[^>]+>/g, "")
      .replace(/[ \t]+/g, " ")
      .replace(/ *\n */g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim(),
  );
}

export function htmlToMarkdown(html: string): string {
  return decodeHtml(
    html
      .replace(/<style[\s\S]*?<\/style>/gi, "")
      .replace(/<script[\s\S]*?<\/script>/gi, "")
      .replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (_match, level, body) =>
        `${"#".repeat(Number(level))} ${stripHtml(body)}\n\n`,
      )
      .replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (_match, href, body) =>
        `[${stripHtml(body)}](${href})`,
      )
      .replace(/<(strong|b)[^>]*>([\s\S]*?)<\/\1>/gi, "**$2**")
      .replace(/<(em|i)[^>]*>([\s\S]*?)<\/\1>/gi, "*$2*")
      .replace(/<code[^>]*>([\s\S]*?)<\/code>/gi, "`$1`")
      .replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, (_match, body) => `- ${stripHtml(body)}\n`)
      .replace(/<br\s*\/?\s*>/gi, "\n")
      .replace(/<\/(p|blockquote|pre|div)>/gi, "\n\n")
      .replace(/<[^>]+>/g, "")
      .replace(/[ \t]+\n/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim(),
  );
}

function inferredTitle(name: string, content: string, format: "markdown" | "html" | "txt"): string {
  if (format === "html") {
    const title = content.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1];
    if (title?.trim()) return decodeHtml(title.trim());
    const heading = content.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1];
    if (heading?.trim()) return stripHtml(heading);
  }
  if (format === "markdown") {
    const heading = content.match(/^\s*#\s+(.+)$/m)?.[1]?.trim();
    if (heading) return heading;
  }
  const stem = basename(name, extname(name)).replace(/[-_]+/g, " ").trim();
  const firstLine = content.split(/\r?\n/, 1)[0]?.trim();
  return stem || firstLine || "Imported piece";
}

export function detectSourceFormat(name: string): ParsedImport["sourceFormat"] {
  const lower = name.toLowerCase();
  if (lower.endsWith(".twyne.json") || lower.endsWith(".json")) return "archive";
  if (lower.endsWith(".html") || lower.endsWith(".htm")) return "html";
  if (lower.endsWith(".txt")) return "txt";
  if (lower.endsWith(".md") || lower.endsWith(".markdown")) return "markdown";
  throw new Error(`Unsupported import file: ${name}`);
}

export function parseImportSource(source: ImportSource): ParsedImport {
  const sourceFormat = detectSourceFormat(source.name);
  if (sourceFormat === "archive") {
    return { sourceFormat, folios: parseArchive(source.content).folios };
  }
  const title = inferredTitle(source.name, source.content, sourceFormat);
  let html: string;
  if (sourceFormat === "markdown") {
    html = marked.parse(source.content, { async: false, breaks: true, gfm: true }) as string;
  } else if (sourceFormat === "html") {
    html = source.content.match(/<body[^>]*>([\s\S]*?)<\/body>/i)?.[1] ?? source.content;
  } else {
    html = source.content
      .split(/\r?\n\s*\r?\n/)
      .map((paragraph) => `<p>${escapeHtml(paragraph).replace(/\r?\n/g, "<br />")}</p>`)
      .join("\n");
  }
  return {
    sourceFormat,
    folios: [{ folio: { name: title, type: sourc…3256 tokens truncated…readFile(name, "utf8"), type })),
    );
    return json(io, await importSources(await clientFrom(io), sources));
  }

  if (action === "export") {
    const parsed = commandArgs(args, {
      format: { type: "string", default: "archive" },
      output: { type: "string" },
    });
    const format = parsed.values.format as ExportFormat;
    if (!(["archive", "markdown", "html", "txt"] as string[]).includes(format)) {
      throw new Error("--format must be archive, markdown, html, or txt");
    }
    const artifact = exportBundles(
      await fetchFolioBundles(await clientFrom(io), parsed.positionals),
      format,
    );
    if (parsed.values.output) {
      await writeFile(parsed.values.output, artifact.content, "utf8");
      return json(io, {
        output: parsed.values.output,
        format: artifact.format,
        mimeType: artifact.mimeType,
      });
    }
    io.stdout.write(artifact.content);
    return;
  }

  throw new Error("Usage: twyne folio list|get|create|update|search|import|export");
}

async function feedbackCommand(args: string[], io: CliIo): Promise<void> {
  const action = args.shift();
  if (action !== "get") throw new Error("Usage: twyne feedback get ID");
  const parsed = commandArgs(args, {});
  const folioId = required(parsed.positionals[0], "folio ID");
  if (parsed.positionals.length > 1) throw new Error("feedback get accepts one ID");
  json(io, await (await clientFrom(io)).getFeedback(folioId));
}

function parseCitationEntries(value: unknown): CitationEntry[] {
  const entries = Array.isArray(value) ? value : [value];
  for (const [index, entry] of entries.entries()) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      throw new Error(`Citation ${index + 1} must be an object`);
    }
    if (typeof (entry as Record<string, unknown>).title !== "string") {
      throw new Error(`Citation ${index + 1} needs a title`);
    }
  }
  return entries as CitationEntry[];
}

async function citationsCommand(args: string[], io: CliIo): Promise<void> {
  const action = args.shift();
  if (action === "list") {
    const parsed = commandArgs(args, {
      "folio-id": { type: "string" },
      search: { type: "string" },
    });
    return json(
      io,
      await (await clientFrom(io)).listCitations({
        ...(parsed.values["folio-id"] ? { folioId: parsed.values["folio-id"] } : {}),
        ...(parsed.values.search ? { search: parsed.values.search } : {}),
      }),
    );
  }
  if (action === "upsert") {
    const parsed = commandArgs(args, {
      "folio-id": { type: "string" },
      file: { type: "string" },
    });
    const folioId = required(parsed.values["folio-id"], "--folio-id");
    const path = required(parsed.values.file, "--file");
    return json(
      io,
      await (await clientFrom(io)).putCitations(folioId, parseCitationEntries(await readJson(path))),
    );
  }
  throw new Error("Usage: twyne citations list|upsert");
}

export async function runCli(args = process.argv.slice(2), io: CliIo = DEFAULT_IO): Promise<number> {
  const command = args.shift();
  if (!command || command === "help" || command === "--help" || command === "-h") {
    io.stdout.write(HELP);
    return 0;
  }
  try {
    if (command === "auth") await authCommand(args, io);
    else if (command === "folio") await folioCommand(args, io);
    else if (command === "feedback") await feedbackCommand(args, io);
    else if (command === "citations") await citationsCommand(args, io);
    else throw new Error(`Unknown command: ${command}`);
    return 0;
  } catch (error) {
    println(io.stderr, `Error: ${error instanceof Error ? error.message : String(error)}`);
    return 1;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = await runCli();
}

#!/usr/bin/env node

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { pathToFileURL } from "node:url";
import * as z from "zod/v4";
import {
  exportBundles,
  fetchFolioBundles,
  importSources,
  type ExportFormat,
} from "./archive.js";
import { TwyneClient } from "./client.js";
import { FOLIO_INCLUDES, type CitationEntry, type FolioInclude } from "./types.js";

export const TWYNE_MCP_TOOL_NAMES = [
  "twyne_list_folios",
  "twyne_get_folio",
  "twyne_create_folio",
  "twyne_update_folio",
  "twyne_search_folios",
  "twyne_import_folios",
  "twyne_export_folios",
  "twyne_get_feedback",
  "twyne_list_citations",
  "twyne_upsert_citations",
] as const;

function textResult(value: unknown) {
  const structuredContent =
    value !== null && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : { result: value };
  return {
    content: [
      {
        type: "text" as const,
        text: JSON.stringify(value, null, 2) ?? String(value),
      },
    ],
    structuredContent,
  };
}

function toolError(error: unknown) {
  return {
    isError: true,
    content: [
      {
        type: "text" as const,
        text: error instanceof Error ? error.message : String(error),
      },
    ],
  };
}

async function resultOf(task: () => Promise<unknown>) {
  try {
    return textResult(await task());
  } catch (error) {
    return toolError(error);
  }
}

const folioType = z.enum(["draft", "notes", "outline"]);
const includeValue = z.enum(FOLIO_INCLUDES);
const folioId = z.string().trim().min(1).describe("Twyne folio ID");
const citationEntry = z.looseObject({
  id: z.string().optional(),
  title: z.string().trim().min(1),
  author: z.string().optional(),
  url: z.string().url().optional(),
  doi: z.string().optional(),
  citationKey: z.string().optional(),
  accessedAt: z.number().optional(),
});

export function registerTwyneTools(server: McpServer, client: TwyneClient): void {
  server.registerTool(
    "twyne_list_folios",
    {
      title: "List Twyne folios",
      description: "List the authenticated writer's Twyne folios with IDs, names, types, and timestamps.",
      inputSchema: {},
      annotations: { readOnlyHint: true, idempotentHint: true },
    },
    async () => resultOf(() => client.listFolios()),
  );

  server.registerTool(
    "twyne_get_folio",
    {
      title: "Get a Twyne folio",
      description:
        "Fetch a folio and selected writing-room data. By default this includes manuscript HTML, brief, critiques, rubric, suggestions, and citations.",
      inputSchema: {
        folioId,
        include: z
          .array(includeValue)
          .optional()
          .describe("Optional fields to include; omit to fetch the complete folio bundle"),
      },
      annotations: { readOnlyHint: true, idempotentHint: true },
    },
    async ({ folioId, include }) =>
      resultOf(async () => {
        const bundle = await client.getFolio(folioId, include as FolioInclude[] | undefined);
        if (!bundle) throw new Error(`Folio not found: ${folioId}`);
        return bundle;
      }),
  );

  server.registerTool(
    "twyne_create_folio",
    {
      title: "Create a Twyne folio",
      description: "Create a draft, notes, or outline folio, optionally with manuscript HTML and a project brief.",
      inputSchema: {
        name: z.string().trim().min(1).max(240),
        type: folioType.optional().default("draft"),
        html: z.string().optional().describe("Tiptap-compatible manuscript HTML"),
        brief: z.unknown().optional(),
      },
      annotations: { destructiveHint: false, idempotentHint: false },
    },
    async ({ name, type, html, brief }) =>
      resultOf(() =>
        client.putFolio({
          folio: { name, type },
          ...(html !== undefined ? { html } : {}),
          ...(brief !== undefined ? { brief } : {}),
        }),
      ),
  );

  server.registerTool(
    "twyne_update_folio",
    {
      title: "Update a Twyne folio",
      description:
        "Update folio metadata, manuscript HTML, or brief. expectedUpdatedAt enables optimistic conflict detection.",
      inputSchema: {
        folioId,
        name: z.string().trim().min(1).max(240).optional(),
        type: folioType.optional(),
        html: z.string().optional(),
        brief: z.unknown().optional(),
        expectedUpdatedAt: z.number().optional(),
      },
      annotations: { destructiveHint: true, idempotentHint: false },
    },
    async ({ folioId, name, type, html, brief, expectedUpdatedAt }) =>
      resultOf(async () => {
        const current = await client.getFolio(folioId, []);
        if (!current) throw new Error(`Folio not found: ${folioId}`);
        return client.putFolio({
          folio: {
            ...current.folio,
            id: folioId,
            name: name ?? current.folio.name,
            type: type ?? current.folio.type,
          },
          ...(html !== undefined ? { html } : {}),
          ...(brief !== undefined ? { brief } : {}),
          ...(expectedUpdatedAt !== undefined ? { expectedUpdatedAt } : {}),
        });
      }),
  );

  server.registerTool(
    "twyne_search_folios",
    {
      title: "Search Twyne folios",
      description: "Search folio names and manuscript text, returning ranked snippets for fast retrieval.",
      inputSchema: {
        query: z.string().trim().min(1),
        limit: z.number().int().min(1).max(50).optional().default(20),
      },
      annotations: { readOnlyHint: true, idempotentHint: true },
    },
    async ({ query, limit }) => resultOf(() => client.searchFolios(query, limit)),
  );

  server.registerTool(
    "twyne_import_folios",
    {
      title: "Import Twyne folios",
      description:
        "Bulk import one or more Twyne archive-v2 JSON bundles or individual Markdown, HTML, and text files supplied as name/content pairs.",
      inputSchema: {
        sources: z
          .array(
            z.object({
              name: z.string().trim().min(1).describe("Filename including .twyne.json, .md, .html, or .txt"),
              content: z.string(),
              type: folioType.optional(),
            }),
          )
          .min(1)
          .max(50),
      },
      annotations: { destructiveHint: false, idempotentHint: false },
    },
    async ({ sources }) => resultOf(() => importSources(client, sources)),
  );

  server.registerTool(
    "twyne_export_folios",
    {
      title: "Export Twyne folios",
      description:
        "Export selected folios, or all folios when IDs are omitted. Archive is the bulk Twyne archive-v2 format; Markdown, HTML, and text require one folio.",
      inputSchema: {
        folioIds: z.array(folioId).max(500).optional(),
        format: z.enum(["archive", "markdown", "html", "txt"]).optional().default("archive"),
      },
      annotations: { readOnlyHint: true, idempotentHint: true },
    },
    async ({ folioIds, format }) =>
      resultOf(async () =>
        exportBundles(await fetchFolioBundles(client, folioIds), format as ExportFormat),
      ),
  );

  server.registerTool(
    "twyne_get_feedback",
    {
      title: "Get Twyne critiques",
      description:
        "Get all feedback for a folio in one fast call: editor notes and replies, rubric results, and actionable suggestions.",
      inputSchema: { folioId },
      annotations: { readOnlyHint: true, idempotentHint: true },
    },
    async ({ folioId }) => resultOf(() => client.getFeedback(folioId)),
  );

  server.registerTool(
    "twyne_list_citations",
    {
      title: "List Twyne citations",
      description:
        "Retrieve saved sources, optionally scoped to a folio or searched by title, author, URL, DOI, or citation key. Use before adding sources to avoid duplicates.",
      inputSchema: {
        folioId: folioId.optional(),
        search: z.string().trim().min(1).optional(),
      },
      annotations: { readOnlyHint: true, idempotentHint: true },
    },
    async ({ folioId, search }) =>
      resultOf(() =>
        client.listCitations({
          ...(folioId ? { folioId } : {}),
          ...(search ? { search } : {}),
        }),
      ),
  );

  server.registerTool(
    "twyne_upsert_citations",
    {
      title: "Save Twyne citations",
      description:
        "Bulk create or update cited sources for a folio. Call this after using external sources so claims can retain their provenance; pass an existing citation ID to update it.",
      inputSchema: {
        folioId,
        entries: z.array(citationEntry).min(1).max(100),
      },
      annotations: { destructiveHint: false, idempotentHint: true },
    },
    async ({ folioId, entries }) =>
      resultOf(() => client.putCitations(folioId, entries as CitationEntry[])),
  );
}

export function createTwyneMcpServer(client: TwyneClient): McpServer {
  const server = new McpServer({ name: "twyne", version: "0.1.0" });
  registerTwyneTools(server, client);
  return server;
}

export async function runMcpServer(): Promise<void> {
  const server = createTwyneMcpServer(await TwyneClient.fromEnvironment());
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runMcpServer().catch((error) => {
    console.error(`twyne-mcp: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  });
}
